source.exploreUrl:
@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});
push("全部🌊分类",null,1,1)
push("🌊全本🌊",`/quanben/list/{{page}}/`,1,1)
	arList=["玄幻魔法","武侠修真","都市言情","历史军事","科幻灵异","游戏竞技","其他类型"]
	arList.map((tag,index)=>{
		url=`/list/${index+1}_{{page}}/`;
		push(tag, url, 1, 0.25);
		});
//java.log(JSON.stringify(sort))
JSON.stringify(sort)

