ruleToc.chapterList:
class.info-chapters.-1@a
<js>
//章节链接+1，修复空白章
list=result.toArray();
l=[];
for(i in list){
	text=list[i].text()
	if(i%6==0 && i!=0){
		num=Number(String(list[i-1]).match(/(\d+)\.html/)[1])+1;
		href=String(list[i-1].attr("href")).replace(/\d+\.html/,num+".html");
		}else{
			href=String(list[i]).match(/href="([^"]+)"/)[1];
			}
	l.push({
		text:text,
		href:href
		})
	l
	}
</js>

